import os
import sys
import tempfile
import types


def _mod(name):
    existing = sys.modules.get(name)
    if existing is not None:
        return existing
    module = types.ModuleType(name)
    sys.modules[name] = module
    parent_name, _, attr = name.rpartition(".")
    if parent_name:
        setattr(_mod(parent_name), attr, module)
    return module


_mod("reportlab")
_mod("reportlab.lib")
pagesizes = _mod("reportlab.lib.pagesizes")
pagesizes.letter = getattr(pagesizes, "letter", (612.0, 792.0))
_mod("reportlab.pdfgen")
canvas_mod = _mod("reportlab.pdfgen.canvas")


