        self._current = []
        self._pages.append(self._current)

    def drawString(self, x, y, text):
        self._current.append((x, y, str(text)))

    def save(self):
        with open(self.filename, "wb") as handle:
            handle.write(b"%PDF-1.4\n%%EOF\n")


if not hasattr(canvas_mod, "Canvas"):
