class Canvas:
    def __init__(self, path, pagesize=None):
        self.path = path
        self.pagesize = pagesize
        self._pages = [[]]
        self._current = self._pages[0]

    def showPage(self):
        self._current = []
        self._pages.append(self._current)

    def drawString(self, x, y, text):
        self._current.append((x, y, text))

    def save(self):
        with open(self.path, "wb") as f:
            f.write(b"%PDF-1.4\n%\xe2\xe3\xcf\xd3\n")
            f.write(b"1 0 obj<< /Type /Catalog /Pages 2 0 R >>endobj\n")
            f.write(b"trailer\n<< /Root 1 0 R >>\nstartxref\n0\n%%EOF\n")
            for page in self._pages:
                for _x, _y, text in page:
                    f.write((text + "\n").encode("latin-1", "replace"))

