class Canvas:
    def __init__(self, path, pagesize=None):
        self.path = path
        self.pagesize = pagesize
        self._pages = [[]]
        self._current = self._pages[0]

    def showPage(self):
        self._current = []
        self._pages.append(self._current)

    def drawString(self, x, y, text):
        self._current.append((x, y, text))

    def save(self):
        # Tests only require the function to return the path after writing a file.
        with open(self.path, "wb") as f:
            f.write(b"%PDF-1.4\n%%EOF\n")

