import os
import sys
import tempfile
import types

# Provide a tiny reportlab stand-in before importing the export module.
if "reportlab" not in sys.modules:
    class _Canvas:
        def __init__(self, path, pagesize=None):
            self.path = path

        def showPage(self):
            pass

        def drawString(self, x, y, text):
            pass

        def save(self):
            with open(self.path, "wb") as f:
                f.write(b"%PDF-1.4\n%%EOF\n")

    _reportlab = types.ModuleType("reportlab")
    _lib = types.ModuleType("reportlab.lib")
    _pagesizes = types.ModuleType("reportlab.lib.pagesizes")
    _pagesizes.letter = (612, 792)
    _pdfgen = types.ModuleType("reportlab.pdfgen")
    _canvas = types.ModuleType("reportlab.pdfgen.canvas")
    _canvas.Canvas = _Canvas
    _reportlab.lib = _lib
    _reportlab.pdfgen = _pdfgen
    _lib.pagesizes = _pagesizes
    _pdfgen.canvas = _canvas
    sys.modules["reportlab"] = _reportlab
    sys.modules["reportlab.lib"] = _lib
    sys.modules["reportlab.lib.pagesizes"] = _pagesizes
    sys.modules["reportlab.pdfgen"] = _pdfgen
    sys.modules["reportlab.pdfgen.canvas"] = _canvas

