"""OCR helpers for the invoice-processing module."""
import re

from PIL import Image, ImageOps

TOTAL_PATTERN = re.compile(
    r"(?:total|amount due)[:\s]*\$?([\d,]+\.\d{2})", re.IGNORECASE
)


def parse_total(text):
    match = TOTAL_PATTERN.search(text)
    if not match:
        return None
    return float(match.group(1).replace(",", ""))


def parse_currency_totals(text, currencies):
    results = {}
    for code in currencies:
        pattern = re.compile(
            rf"{re.escape(code)}[:\s]*\$?([\d,]+\.\d{{2}})", re.IGNORECASE
        )
        match = pattern.search(text)
        if match:
            results[code] = float(match.group(1).replace(",", ""))
    return results


def _preprocess_for_ocr(image):
    """Grayscale + autocontrast so low-contrast scans remain readable."""
    processed = image.convert("L")
    return ImageOps.autocontrast(processed)


def extract_text(image_path):
    try:
        import pytesseract
    except ImportError:
        return ""

    try:
        with Image.open(image_path) as image:
            processed = _preprocess_for_ocr(image)
            return pytesseract.image_to_string(processed)
    except Exception:
        return ""


def extract_totals(image_path):
    return parse_total(extract_text(image_path))


def extract_currency_totals(image_path, currencies):
    return parse_currency_totals(extract_text(image_path), currencies)

