def geocode(address):
    normalized = normalize_address(address)
    if not normalized:
        return None
    params = {"q": normalized, "format": "json", "limit": 1}
    response = requests.get(NOMINATIM_URL, params=params, timeout=5)
    response.raise_for_status()
    results = response.json()
    if not results:
        return None
    return float(results[0]["lat"]), float(results[0]["lon"])


def geocode_batch(addresses):
    return [geocode(a) for a in addresses]

from unittest.mock import Mock, patch

from src.geocode import extract_zip, geocode, normalize_address


def test_normalize_address_collapses_whitespace():
    assert normalize_address("123   Main St") == "123 Main St"


def test_normalize_address_strips_edges():
    assert normalize_address("  123 Main St  ") == "123 Main St"


def test_normalize_address_idempotent():
    addr = normalize_address("123 Main St, Springfield")
    assert normalize_address(addr) == addr


def test_extract_zip_basic():
    assert extract_zip("123 Main St, Springfield, IL 62704") == "62704"


def test_extract_zip_zip_plus_four():
    assert extract_zip("123 Main St, Springfield, IL 62704-1234") == "62704-1234"


def test_extract_zip_missing_returns_none():
    assert extract_zip("123 Main St, Springfield, IL") is None


def test_extract_zip_ignores_non_zip_digits():
    assert extract_zip("Suite 4, 123 Main St, IL 62704") == "62704"


def _json_response(payload):
    response = Mock()
    response.raise_for_status.return_value = None
    response.json.return_value = payload
    return response


@patch("src.geocode.requests.get")
def test_geocode_full_address(mock_get):
    mock_get.return_value = _json_response([{"lat": "37.422", "lon": "-122.084"}])
    result = geocode("1600 Amphitheatre Parkway, Mountain View, CA")
    assert result is not None


@patch("src.geocode.requests.get")
def test_geocode_partial_address(mock_get):
    mock_get.return_value = _json_response([{"lat": "39.7817", "lon": "-89.6501"}])
    result = geocode("Springfield, IL")
    assert result is not None


@patch("src.geocode.requests.get")
def test_geocode_invalid_address(mock_get):
    result = geocode("")
    assert result is None
    mock_get.assert_not_called()
